SELECT  FROM ca_location

    AND (

            1=1

                1=0

                    OR dept_id IN
                    #{dept}



    )

        AND (location_code LIKE CONCAT('%', #{keyword}, '%') OR location_name LIKE CONCAT('%', #{keyword}, '%'))

    AND status=#{status}
    AND dept_id=#{deptId}
    AND location_type=#{locationType}

ORDER BY order_num, location_id

SELECT  

    AND (

            1=1

                1=0

                    OR a.dept_id IN
                    #{dept}

                OR a.keeper_user_id=#{selfUserId}


    )

        AND (a.asset_code LIKE CONCAT('%', #{keyword}, '%') OR a.asset_name LIKE CONCAT('%', #{keyword}, '%'))

    AND a.asset_status=#{status}
    AND a.condition_status=#{conditionStatus}
    AND a.dept_id=#{deptId}
    AND a.category_id=#{categoryId}
    AND a.location_id=#{locationId}
    AND a.registered_time >= #{beginTime}
    AND a.registered_time <= #{endTime}

ORDER BY a.asset_id DESC
